mapper.select:
SELECT id FROM account
WHERE user_id = #{userId}
  AND (
    number = #{number}
    OR account_id = #{number}
    OR company = #{company}
  )
ORDER BY id DESC LIMIT 1

SELECT id FROM card
WHERE user_id = #{userId}
  AND (
    number = #{number}
    OR card_id = #{number}
    OR company = #{company}
  )
ORDER BY id DESC LIMIT 1
